// Fill in the IDs of your test setup and the Localmind version under test, then run the
// workflow. For the development version, give the next release (for example 1.7.0).
return [{ json: {
    "agentId": "PASTE-ID-OF-AN-AGENT-WITH-CODE-EXECUTION",
    "spaceId": "PASTE-SPACE-ID",
    "folder": "release-check",
    "localmindVersion": "PASTE-LOCALMIND-VERSION"
  } }];

// 1.5 MB, with a name that carries a Windows path, as browser forms send it: only its last part counts.
const name = `release-large-${Date.now()}.txt`;
return [{ json: { name }, binary: { data: {
  data: Buffer.from('x'.repeat(1500000)).toString('base64'),
  mimeType: 'text/plain',
  fileName: `C:\\fakepath\\${name}`,
} } }];

// A PDF with a secret code, a CSV (column b adds up to 16) and an executable, which Localmind refuses.
const objs = [
  "<< /Type /Catalog /Pages 2 0 R >>",
  "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
  "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 420 144] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>",
  null,
  "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
];
const content = "BT /F1 16 Tf 20 80 Td (The secret code is LIGHTHOUSE-7319.) Tj ET";
let pdf = "%PDF-1.4
"; const offsets = [];
objs.forEach((o, i) => { offsets.push(pdf.length); pdf += (i + 1) + " 0 obj
" + (o ?? "<< /Length " + content.length + " >>
stream
" + content + "
endstream") + "
endobj
"; });
const xref = pdf.length;
pdf += "xref
0 " + (objs.length + 1) + "
0000000000 65535 f 
" + offsets.map((o) => String(o).padStart(10, "0") + " 00000 n 
").join("") + "trailer
<< /Size " + (objs.length + 1) + " /Root 1 0 R >>
startxref
" + xref + "
%%EOF
";
const csv = "a;b
1;2
3;4
5;10
";
return [{ json: {}, binary: {
  csv: { data: Buffer.from(csv).toString("base64"), mimeType: "text/csv", fileName: "Zahlen Übersicht.csv" },
