  pdf: { data: Buffer.from(pdf, "latin1").toString("base64"), mimeType: "application/pdf", fileName: "Notiz.pdf" },
  exe: { data: "TVqQAAMAAAAEAAAA//8AALgAAAAAAAAAQAAAAAAAAAA=", mimeType: "application/x-msdownload", fileName: "tool.exe" },
} }];

// One report for everything above; the nodes before it go on after an error, so that the
// conversation and the file are always deleted.
const result = (name) => $(name).first().json;
const problems = [];
const errorOf = (name) => String(result(name).error ?? '');

// The version under test decides what is expected, so a 1.7.0 that falls back to the older
// behaviour fails instead of passing as "before 1.7.0".
const version = String($('Settings').first().json.localmindVersion ?? '').trim();
const parts = /^(\d+)\.(\d+)\.\d+/.exec(version);
if (!parts) {
  throw new Error(`Settings: give localmindVersion, the Localmind version under test (such as 1.6.0 or 1.7.0), not "${version}"`);
}
const uploads = Number(parts[1]) > 1 || (Number(parts[1]) === 1 && Number(parts[2]) >= 7);

const upload = result('Upload Large File');
const folder = $('Settings').first().json.folder;
if (!/^release-large-\d+\.txt$/.test(String(upload.path ?? '').replace(`${folder}/`, ''))) {
  problems.push(`Upload: expected the name without its Windows path, got ${upload.path ?? errorOf('Upload Large File')}`);
}
if (!errorOf('Download Over Limit').includes("larger than 1 MB ('Max File Size (MB)')")) {
  problems.push(`Download over the limit: ${errorOf('Download Over Limit') || 'it was downloaded anyway'}`);
}
if (result('Download In Full').size !== 1500000) {
  problems.push(`Full download: ${JSON.stringify(result('Download In Full'))}`);
}
if (result('Delete Large File').deleted !== true) problems.push(`Delete file: ${errorOf('Delete Large File')}`);

// Localmind 1.7.0 refuses an executable upload; before 1.7.0 the node refuses it itself.
const executable = errorOf('Send Executable');
const executableRefused = uploads
  ? /refused the attachment "tool\.exe" \(upload_type_runnable\)/
  : /"tool\.exe" .* cannot be attached/;
if (!executableRefused.test(executable)) {
  problems.push(`Executable (Localmind ${version}): ${executable || 'it was sent'}`);
}

// From 1.7.0 the PDF and the CSV are uploaded and the agent answers from both; before 1.7.0 the
// PDF is refused with a pointer to 1.7.0, and the message is not sent.
const both = result('Send PDF and CSV');
const attachments = uploads ? 'uploaded (Localmind 1.7.0 or later)' : 'PDF refused, as before Localmind 1.7.0';
if (uploads) {
  if (!both.text) {
    problems.push(`PDF and CSV (Localmind ${version}): expected an answer from both files, got ${both.error}`);
  } else if (!both.text.includes('LIGHTHOUSE-7319') || !/\b16\b/.test(both.text)) {
    problems.push(`PDF and CSV: the answer lacks the code or the sum: ${both.text}`);
  }
} else if (!/"Notiz\.pdf" \(application\/pdf\) cannot be attached/.test(String(both.error))) {
  problems.push(`PDF and CSV (Localmind ${version}): expected the PDF to be refused, got ${both.text ?? both.error}`);
}
// A CSV goes along on every version: uploaded from 1.7.0, as text before.
const csvOnly = result('Send CSV Only');
if (!/\b16\b/.test(String(csvOnly.text ?? ''))) problems.push(`CSV only: ${csvOnly.text ?? csvOnly.error}`);
if (result('Delete Conversation').deleted !== true) problems.push(`Delete conversation: ${errorOf('Delete Conversation')}`);

// From 1.7.0 a generated CSV always comes with an AI label, "<name>.provenance.json", marked as
// such; before 1.7.0 there is none.
const files = result('Ask For CSV').files ?? [];
const csvFile = files.find((file) => file.fileName === 'release-labels.csv');
if (!csvFile?.binaryProperty) problems.push(`Ask: release-labels.csv missing or not downloaded: ${JSON.stringify(files)}`);
const labels = files.filter((file) => file.fileName.endsWith('.provenance.json'));
if (uploads && !labels.some((label) => label.fileName === 'release-labels.csv.provenance.json')) {
  problems.push(`AI label (Localmind ${version}): release-labels.csv.provenance.json missing: ${JSON.stringify(files)}`);
}
if (!uploads && labels.length) {
  problems.push(`AI label (Localmind ${version}): none expected before 1.7.0, got ${JSON.stringify(labels)}`);
}
if (labels.some((label) => label.provenance !== true || !label.binaryProperty)) {
  problems.push(`AI label not marked or not downloaded: ${JSON.stringify(labels)}`);
}
// A download link behind a path prefix (a proxy) leads to the same file.
if (csvFile && result('Download Behind Prefix').size !== csvFile.size) {
  problems.push(`Link behind a path prefix: ${JSON.stringify(result('Download Behind Prefix'))}`);
}

if (problems.length) throw new Error(problems.join(' | '));
return [{ json: {
  passed: 'Attachments, downloads and AI labels',
  attachments,
  localmindVersion: version,
  aiLabels: labels.length ? 'present (Localmind 1.7.0 or later)' : 'none (before Localmind 1.7.0)',
} }];
